@code {
    private string _activeSection = "profile";
    private string? _toastMessage;
    private string _toastType = "toast-success";
    private System.Timers.Timer? _toastTimer;

    private readonly record struct SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }

    private void ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastType = isError ? "toast-error" : "toast-success";
        _toastTimer?.Dispose();
        _toastTimer = new System.Timers.Timer(3000);
        _toastTimer.Elapsed += (_, _) =>
        {
            InvokeAsync(() =>
            {
                _toastMessage = null;
                StateHasChanged();
            });
            _toastTimer?.Dispose();
        };
        _toastTimer.AutoReset = false;
        _toastTimer.Start();
        StateHasChanged();
    }

    private void DismissToast()
    {
        _toastMessage = null;
        _toastTimer?.Dispose();
    }

    public void Dispose()
    {
        _toastTimer?.Dispose();
    }
}
