    background: #dc3545;
    color: #fff;
    border: none;
    border-radius: 5px;
    font-size: 0.825rem;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-danger:hover {
    background: #c82333;
}

/* Toggle switch */
.toggle-row {
