{"file_text": "@using sv_d5759285a47f45abadc1f9558f860275.Services
@using sv_d5759285a47f45abadc1f9558f860275.Models
@inject ISettingsService SettingsService

<div class="section-header">
    <h2>Appearance</h2>
    <p>Customize the look and feel of the application.</p>
</div>

@if (_loading)
{
    <p>Loading appearance settings…</p>
}
else
{
    <!-- Theme -->
    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in _themes)
            {
                var t = theme;
                <div class="radio-option">
                    <input type="radio" name="theme" id="theme-@t" value="@t"
                           checked="@(_theme == t)"
                           @onchange="() => _theme = t" />
                    <label for="theme-@t">@t</label>
                </div>
            }
        </div>
    </div>

    <!-- Font Size -->
    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in _fontSizes)
            {
                var s = size;
                <div class="radio-option">
                    <input type="radio" name="fontSize" id="fs-@s" value="@s"
                           checked="@(_fontSize == s)"
                           @onchange="() => _fontSize = s" />
                    <label for="fs-@s">@s</label>
                </div>
            }
        </div>
    </div>

    <!-- Language -->
    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="_language">
            @foreach (var lang in _languages)
            {
                <option value="@lang">@lang</option>
            }
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="toggle-row">
        <span class="toggle-label">Compact Mode</span>
        <label class="toggle-switch">
            <input type="checkbox" @bind="_compactMode" />
            <span class="toggle-slider"></span>
        </label>
    </div>

    <!-- Live Preview -->
    <div class="appearance-preview" style="@GetPreviewStyle()">
        <h5>Live Preview</h5>
        <div class="preview-card" style="@GetPreviewCardStyle()">
            <p class="preview-text" style="@GetPreviewFontStyle()">
                This is a preview of your selected appearance settings. The theme is <strong>@_theme</strong>,
                font size is <strong>@_fontSize</strong>, and compact mode is
                <strong>@(_compactMode ? "on" : "off")</strong>.
            </p>
            <span class="preview-btn" style="@GetPreviewButtonStyle()">Sample Button</span>
        </div>
        <p style="font-size: 0.8rem; opacity: 0.6; margin: 0;">Language: @_language</p>
    </div>

    <div class="btn-actions">
        <button class="btn-save" @onclick="SaveAppearance" disabled="@_saving">
            @(_saving ? "Saving…" : "Save")
        </button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast-notification toast-success" style="position: relative; bottom: auto; right: auto; margin-top: 1rem; display: inline-flex;" role="alert">
            @_message
        </div>
    }
}

@code {
    private bool _loading = true;
    private bool _saving;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private string? _message;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Portuguese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        _message = null;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance settings saved!";
        _saving = false;
    }

    private string GetPreviewStyle()
    {
        var bg = _theme == "Dark" ? "#1e1e2e" : "#fff";
        var color = _theme == "Dark" ? "#e0e0e0" : "#333";
        var padding = _compactMode ? "0.75rem" : "1.25rem";
        var border = _theme == "Dark" ? "#444" : "#e0e0e0";
        return $"background: {bg}; color: {color}; padding: {padding}; border-color: {border};";
    }

    private string GetPreviewCardStyle()
    {
        var bg = _theme == "Dark" ? "#2a2a3d" : "#fafbfc";
        var border = _theme == "Dark" ? "#555" : "#e0e0e0";
        var padding = _compactMode ? "0.5rem" : "0.85rem";
        return $"background: {bg}; border-color: {border}; padding: {padding};";
    }

    private string GetPreviewFontStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "0.8rem",
            "Large" => "1.1rem",
            _ => "0.95rem"
        };
        var lineHeight = _compactMode ? "1.3" : "1.5";
        return $"font-size: {size}; line-height: {lineHeight};";
    }

    private string GetPreviewButtonStyle()
    {
        var bg = _theme == "Dark" ? "#4a90d9" : "#1b6ec2";
        var size = _fontSize switch
        {
            "Small" => "0.75rem",
            "Large" => "0.95rem",
            _ => "0.85rem"
        };
        var padding = _compactMode ? "0.25rem 0.75rem" : "0.35rem 1rem";
        return $"background: {bg}; color: #fff; font-size: {size}; padding: {padding};";
    }
}
