@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar" aria-label="Settings sections">
        <h4 class="sidebar-title">Settings</h4>
        @foreach (var section in _sections)
        {
            <button class="sidebar-item @(section.Key == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section.Key)"
                    aria-current="@(section.Key == _activeSection ? "page" : null)">
                <span class="sidebar-icon">@section.Icon</span>
                <span>@section.Label</span>
            </button>
        }
    </nav>

    <main class="settings-content">
        @if (_activeSection == "profile")
        {
            <ProfileSection />
        }
        else if (_activeSection == "notifications")
        {
            <NotificationsSection />
        }
        else if (_activeSection == "security")
        {
            <SecuritySection />
        }
        else if (_activeSection == "appearance")
        {
            <AppearanceSection />
        }
    </main>
</div>

@if (!string.IsNullOrEmpty(_toastMessage))
{
    <div class="toast-notification @(_toastType)" role="alert">
        <span>@_toastMessage</span>
        <button class="toast-close" @onclick="DismissToast" aria-label="Dismiss">&times;</button>
    </div>
}

@code {
    private string _activeSection = "profile";
    private string? _toastMessage;
    private string _toastType = "toast-success";
    private System.Timers.Timer? _toastTimer;

    private readonly record struct SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }

    private void ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastType = isError ? "toast-error" : "toast-success";
        _toastTimer?.Dispose();
        _toastTimer = new System.Timers.Timer(3000);
        _toastTimer.Elapsed += (_, _) =>
        {
            InvokeAsync(() =>
            {
                _toastMessage = null;
                StateHasChanged();
            });
            _toastTimer?.Dispose();
        };
        _toastTimer.AutoReset = false;
        _toastTimer.Start();
        StateHasChanged();
    }

    private void DismissToast()
    {
        _toastMessage = null;
        _toastTimer?.Dispose();
    }

    public void Dispose()
    {
        _toastTimer?.Dispose();
    }
}

