@using sv_d5759285a47f45abadc1f9558f860275.Services
@using sv_d5759285a47f45abadc1f9558f860275.Models
@inject ISettingsService SettingsService

<div class="section-header">
    <h2>Profile</h2>
    <p>Manage your personal information and public profile.</p>
</div>

@if (_loading)
{
    <p>Loading profile…</p>
}
else
{
    <div class="avatar-preview">
        @if (!string.IsNullOrWhiteSpace(_avatarUrl))
        {
            <img class="avatar-img" src="@_avatarUrl" alt="Avatar preview" />
        }
        else
        {
            <div class="avatar-placeholder">👤</div>
        }
        <div>
            <div><strong>@_displayName</strong></div>
            <div class="avatar-url">@(string.IsNullOrWhiteSpace(_avatarUrl) ? "No avatar URL set" : _avatarUrl)</div>
        </div>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="_displayName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="_email" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="avatarUrl">Avatar URL</label>
        <input id="avatarUrl" type="text" @bind="_avatarUrl" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="_bio" @bind:event="oninput"></textarea>
    </div>

    <div class="btn-actions">
        <button class="btn-save" @onclick="SaveProfile" disabled="@_saving">
            @(_saving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn-discard" @onclick="DiscardChanges">Discard Changes</button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast-notification @(_messageIsError ? "toast-error" : "toast-success")" style="position: relative; bottom: auto; right: auto; margin-top: 1rem; display: inline-flex;" role="alert">
            @_message
        </div>
    }
}

@code {
    private bool _loading = true;
    private bool _saving;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private string? _message;
    private bool _messageIsError;

    // Saved state for discard
    private UserProfile? _savedProfile;

    protected override async Task OnInitializedAsync()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveProfile()
    {
        _saving = true;
        _message = null;
        try
        {
            var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(profile);
            _savedProfile = profile;
            _message = "Profile saved successfully!";
            _messageIsError = false;
        }
        catch
        {
            _message = "Failed to save profile.";
            _messageIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private void DiscardChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
            _message = null;
        }
    }
}

