@using sv_d5759285a47f45abadc1f9558f860275.Services
@using sv_d5759285a47f45abadc1f9558f860275.Models
@inject ISettingsService SettingsService

<div class="section-header">
    <h2>Notifications</h2>
    <p>Control how and when you receive notifications.</p>
</div>

@if (_loading)
{
    <p>Loading notification preferences…</p>
}
else
{
    <div class="toggle-row">
        <span class="toggle-label">Email Notifications</span>
        <label class="toggle-switch">
            <input type="checkbox" @bind="_emailNotifications" />
            <span class="toggle-slider"></span>
        </label>
    </div>

    <div class="toggle-row">
        <span class="toggle-label">Push Notifications</span>
        <label class="toggle-switch">
            <input type="checkbox" @bind="_pushNotifications" />
            <span class="toggle-slider"></span>
        </label>
    </div>

    <div class="toggle-row">
        <span class="toggle-label">Weekly Digest</span>
        <label class="toggle-switch">
            <input type="checkbox" @bind="_weeklyDigest" />
            <span class="toggle-slider"></span>
        </label>
    </div>

    <h5 style="margin-top: 1.5rem; margin-bottom: 0.5rem;">Muted Channels</h5>
    <p style="color: #666; font-size: 0.85rem; margin-bottom: 0.75rem;">Check the channels you want to mute.</p>

    <div class="channels-list">
        @foreach (var channel in _allChannels)
        {
            var ch = channel;
            <div class="channel-item">
                <input type="checkbox"
                       id="ch-@ch"
                       checked="@_mutedChannels.Contains(ch)"
                       @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                <label for="ch-@ch">#@ch</label>
            </div>
        }
    </div>

    <div class="btn-actions">
        <button class="btn-save" @onclick="SavePreferences" disabled="@_saving">
            @(_saving ? "Saving…" : "Save Preferences")
        </button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast-notification toast-success" style="position: relative; bottom: auto; right: auto; margin-top: 1rem; display: inline-flex;" role="alert">
            @_message
        </div>
    }
}

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private string? _message;

    private static readonly List<string> _allChannels =
        ["general", "announcements", "random", "off-topic", "watercooler", "design-reviews", "engineering", "support"];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        _saving = true;
        _message = null;
        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _message = "Notification preferences saved!";
        _saving = false;
    }
}

