@using sv_d5759285a47f45abadc1f9558f860275.Services
@using sv_d5759285a47f45abadc1f9558f860275.Models
@inject ISettingsService SettingsService

<div class="section-header">
    <h2>Security</h2>
    <p>Manage your password, two-factor authentication, and active sessions.</p>
</div>

@if (_loading)
{
    <p>Loading security settings…</p>
}
else
{
    <!-- Change Password -->
    <div class="expandable-panel">
        <button class="expandable-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
            <span>Change Password</span>
            <span class="expandable-chevron @(_passwordPanelOpen ? "open" : "")">▼</span>
        </button>
        @if (_passwordPanelOpen)
        {
            <div class="expandable-body">
                <div class="form-group">
                    <label for="currentPw">Current Password</label>
                    <input id="currentPw" type="password" @bind="_currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPw">New Password</label>
                    <input id="newPw" type="password" @bind="_newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPw">Confirm Password</label>
                    <input id="confirmPw" type="password" @bind="_confirmPassword" />
                </div>
                @if (!string.IsNullOrEmpty(_passwordError))
                {
                    <div class="field-error">@_passwordError</div>
                }
                @if (!string.IsNullOrEmpty(_passwordSuccess))
                {
                    <div class="toast-notification toast-success" style="position: relative; bottom: auto; right: auto; margin-bottom: 0.75rem; display: inline-flex;" role="alert">
                        @_passwordSuccess
                    </div>
                }
                <button class="btn-save" @onclick="UpdatePassword" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating…" : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div style="margin-bottom: 1.5rem;">
        <h5 style="margin-bottom: 0.5rem;">Two-Factor Authentication</h5>
        <div class="toggle-row">
            <span class="toggle-label">
                <span class="status-indicator">
                    <span class="status-dot @(_twoFactorEnabled ? "enabled" : "disabled")"></span>
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </span>
            <label class="toggle-switch">
                <input type="checkbox" @bind="_twoFactorEnabled" />
                <span class="toggle-slider"></span>
            </label>
        </div>
        @if (_lastPasswordChange.HasValue)
        {
            <p style="font-size: 0.825rem; color: #888; margin-top: 0.5rem;">
                Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }
    </div>

    <!-- Active Sessions -->
    <h5 style="margin-bottom: 0.5rem;">Active Sessions</h5>
    @if (_sessions.Count == 0)
    {
        <p style="color: #888;">No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in _sessions)
                {
                    <tr>
                        <td>
                            @session.Device
                            @if (session == _sessions.First())
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                        <td>@session.Location</td>
                        <td>@FormatLastActive(session.LastActive)</td>
                        <td>
                            @if (session != _sessions.First())
                            {
                                <button class="btn-danger" @onclick="() => ConfirmRevoke(session)">Revoke</button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@if (_sessionToRevoke is not null)
{
    <div class="confirm-overlay" @onclick="CancelRevoke">
        <div class="confirm-dialog" @onclick:stopPropagation="true">
            <h4>Revoke Session</h4>
            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from @_sessionToRevoke.Location? This will sign out that device immediately.</p>
            <div class="confirm-actions">
                <button class="btn-cancel" @onclick="CancelRevoke">Cancel</button>
                <button class="btn-danger" @onclick="RevokeSession" disabled="@_revoking">
                    @(_revoking ? "Revoking…" : "Revoke Session")
                </button>
            </div>
        </div>
    </div>
}

@code {
    private bool _loading = true;
    private bool _passwordPanelOpen;
    private bool _changingPassword;
    private bool _revoking;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();

    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private string? _passwordSuccess;

    private ActiveSession? _sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions.ToList();
        _loading = false;
    }

    private async Task UpdatePassword()
    {
        _passwordError = null;
        _passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _changingPassword = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _lastPasswordChange = DateTime.UtcNow;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordSuccess = "Password updated successfully!";
        _changingPassword = false;
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
        _sessionToRevoke = null;
        _revoking = false;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var elapsed = DateTime.UtcNow - lastActive;
        if (elapsed.TotalMinutes < 1) return "Just now";
        if (elapsed.TotalMinutes < 60) return $"{(int)elapsed.TotalMinutes}m ago";
        if (elapsed.TotalHours < 24) return $"{(int)elapsed.TotalHours}h ago";
        return $"{(int)elapsed.TotalDays}d ago";
    }
}

